output_text:
[
  {
    "id": "take_entry_cart",
    "text": "Before shopping, the customer must take the available cart from the entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entrance_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "no_interact_without_cart_except_cart",
    "text": "A shopper who is not holding the cart may not interact with store objects except to pick up the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "non_cart_interaction_without_cart": {
          "pre": {
            "and": [
              "without_cart",
              "INTERACT",
              {
                "not": "PICKUP_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "non_cart_interaction_without_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Required items should be collected only while the shopper is holding the cart, not loose by hand.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "loose_item_pickup": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "loose_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_in_aisles",
    "text": "A shopper may not walk through the supermarket aisles while carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_loose_item": "handFull"
      },
      "events": {
        "walk_with_loose_item": {
          "pre": {
            "and": [
              "carrying_loose_item",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "walk_with_loose_item"
    }
  },
  {
    "id": "return_cart_after_items",
    "text": "After collecting any item, the shopper must return the cart to the designated return point before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "has_cart": "hasCart",
        "cart_parked_at_return_point": "cartAt(0,1)"
      },
      "events": {
        "collect_item_with_cart": {
          "pre": {
            "and": [
              "has_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart": {
          "pre": {
            "and": [
              "cart_return_point",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "cart_parked_at_return_point",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item_with_cart",
      "discharge": "return_cart"
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "The cart may be put down only at the designated return point near cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)"
      },
      "events": {
        "leave_cart_away_from_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "cart_return_point"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_return"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper may exit only after the cart has been parked at the return point.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_point": "cartAt(0,1)"
      },
      "events": {
        "exit_before_cart_returned": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "cart_parked_at_return_point"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_before_cart_returned"
    }
  },
  {
    "id": "no_carts_in_exit_zone",
    "text": "Shopping carts are prohibited in the pedestrian exit and checkout zone on the east side of the store.",
    "abstraction": {
      "state_properties": {
        "pedestrian_exit_zone": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "has_cart",
          "pedestrian_exit_zone"
        ]
      }
    }
  },
  {
    "id": "turn_back_after_eggs_with_cart",
    "text": "After collecting eggs from the lower egg shelf at cell (6,4), a shopper with a cart must turn back west rather than continue east.",
    "abstraction": {
      "state_properties": {
        "lower_egg_pickup_cell": "at(6,4)",
        "has_cart": "hasCart"
      },
      "events": {
        "pickup_lower_eggs_with_cart": {
          "pre": {
            "and": [
              "lower_egg_pickup_cell",
              "has_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "west_turn_from_lower_eggs": {
          "pre": {
            "and": [
              "lower_egg_pickup_cell",
              "has_cart",
              "W"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_lower_eggs_with_cart",
      "discharge": "west_turn_from_lower_eggs"
    }
  }
]
